package com.bank.availability.dep;

import java.math.BigDecimal;
import java.util.concurrent.ThreadLocalRandom;

// The dependency: 99.9% available. 1 in 1000 calls fails (simulating downtime).
public class CoreLedger {
    private final double availability;
    public CoreLedger(double availability) { this.availability = availability; }
    public BigDecimal readBalance(String accountId) {
        if (ThreadLocalRandom.current().nextDouble() > availability)
            throw new RuntimeException("CoreLedger unavailable");
        return new BigDecimal("1000000");
    }
}
