package com.bank.availability.read;

import com.bank.availability.dep.CoreLedger;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Reads: try ledger; on failure serve CACHED (degraded) → availability decoupled from ledger.
public class BalanceReadPath {
    private static final Logger log = Logger.getLogger(BalanceReadPath.class.getName());
    private final CoreLedger ledger;
    private final Map<String, BigDecimal> cache = new HashMap<>();

    public BalanceReadPath(CoreLedger ledger) { this.ledger = ledger; }

    // Returns a valid response (fresh OR stale) — counts as SUCCESS either way.
    public String getBalance(String accountId) {
        try {
            BigDecimal fresh = ledger.readBalance(accountId);
            cache.put(accountId, fresh);                     // refresh cache on success
            return "FRESH " + fresh;
        } catch (RuntimeException ledgerDown) {
            BigDecimal stale = cache.get(accountId);
            if (stale != null) {
                log.warning(() -> "Ledger down — serving STALE balance for " + accountId);
                return "STALE " + stale;                     // degraded but still a success
            }
            throw ledgerDown;                                // only fails if no cache at all
        }
    }
}
