package com.bank.availability.write;

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.logging.Logger;

// Writes: durably ACCEPT and return success; settle against ledger later with retries.
// Submission availability depends on the durable accept, NOT the ledger being up now.
public class TransferAsyncPath {
    private static final Logger log = Logger.getLogger(TransferAsyncPath.class.getName());
    private final Queue<String> inbox = new ArrayDeque<>();   // durable accept (modelled)

    public String submit(String transferId, String payload) {
        inbox.add(transferId + ":" + payload);                // durable write = the success
        log.fine(() -> "Accepted transfer " + transferId + " for async settlement");
        return "ACCEPTED";                                    // success independent of ledger
    }
    public int pending() { return inbox.size(); }
}
